go.solution:
package main

import "fmt"

func bigger(a, b int) int {
	// Go has no conditional expression, so a short if takes its place.
	if a > b {
		return a
	}
	return b
}

func main() {
	var a, b int
	fmt.Scan(&a, &b)
	fmt.Println(bigger(a, b))
}

